# compositor.map — the frame that puts surfaces on the screens (issue 603)
#
# The 60 Hz tick is not a box. src/system/107-compositor.c arms an engine
# timer that writes into this program's argument 0 once every frame,
# measured from the previous deadline, on a timer of its own so the input
# frame (501) and this one run on different cores at once.
#
# A box cannot remember, so the frame number rides a wire that points
# backwards, as the input frame's does: `first_frame` puts 0 on it once,
# and each tick meets the previous frame and sends the next one round
# again. Only one frame number is ever on that wire, so only one frame is
# ever being composited, however many cores are free.

boxes = ../boxes/

station first_frame (boxes/062-arithmetic.c:constant)
  in 0 = 0
  out 0 - composite.1

station composite (boxes/108-compositor.c:composite)
  in 0 - 0$
  in 1 - first_frame.0
  in 1 - composite.0
  out 0 - composite.1
